import{_ as o,o as a,c as t,a3 as r}from"./chunks/framework.D5HvAqso.js";const h=JSON.parse('{"title":"What is DragDoll?","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://niklasramo.github.io/dragdoll/introduction"}],["meta",{"property":"og:url","content":"https://niklasramo.github.io/dragdoll/introduction"}]]},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1776419620000}'),s={name:"introduction.md"};function n(i,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="what-is-dragdoll" tabindex="-1">What is DragDoll? <a class="header-anchor" href="#what-is-dragdoll" aria-label="Permalink to &quot;What is DragDoll?&quot;">​</a></h1><p>DragDoll gives you all the primitives for a production-grade drag-and-drop system — sensors, draggables, droppables, and collision detection. Build sortable lists, kanban boards, design canvases, or something entirely new.</p><p>At its core, DragDoll is built on the concept of <a href="/dragdoll/sensor"><em>sensors</em></a>, which are responsible for listening to user input events (or any events, for that matter) and emitting drag events based on those inputs. While DragDoll comes with a few built-in sensors, you can also create your own to listen to any kind of input events you desire.</p><p>To actually move elements around, DragDoll provides the <a href="/dragdoll/draggable"><code>Draggable</code></a> class. This class acts as an orchestrator for any number of sensors and moves DOM elements based on the drag events emitted by the provided sensors. The <a href="/dragdoll/draggable"><code>Draggable</code></a> class features a simple and functional API that allows you to control the drag process explicitly from start to finish.</p><p>For complete drag and drop experiences, DragDoll also provides <a href="/dragdoll/dnd-observer"><code>DndObserver</code></a> and <a href="/dragdoll/droppable"><code>Droppable</code></a> classes, which handle collision detection between draggable elements and drop targets. Together, these three classes create a powerful foundation for building sophisticated drag and drop interfaces.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>📡   <strong>Sweet Sensors</strong>: Pointer, keyboard, or roll your own. Sensors normalize any input into unified drag events, giving you complete control over interactions.</p><p>🤏   <strong>Dynamic Draggables</strong>: A highly customizable Draggable system with autoscrolling superpowers, drag previews, and position modifiers. Complex scenarios made effortless.</p><p>🎯   <strong>Classy Collisions</strong>: An extendable, cache-optimized collision detection system you can build on. Ships with a visibility-aware detector that handles overflow clipping and scroll containers for you.</p><p>🔄   <strong>True Transforms</strong>: Finally, transformed elements can be dragged normally. Rotate, scale, skew to your heart&#39;s content.</p><p>😴   <strong>Dreamy DX</strong>: Smart defaults get you moving fast. Rich events and extension points give you full control when you need it.</p><p>⚡   <strong>Snappy Swipes</strong>: Pooled events, batched DOM reads/writes, cached measurements. Performance is built to the core.</p><p>💝   <strong>Lovely License</strong>: 100% MIT licensed, spread the love.</p>',13)])])}const u=o(s,[["render",n]]);export{h as __pageData,u as default};
